/* ===== BIOLOGIA unità 1–4 (b1a–b4d), seconda tornata: esempi svolti, domande in più, metodo ===== */
(function(){
const T=id=>BIO_TOPICS.find(t=>t.id===id);

/* ---------- Paragrafi di metodo ---------- */
T("b1a").sp.push("Come si ragiona negli esercizi: per i virus parti sempre dal tipo di acido nucleico e chiediti «come fa questo virus a ottenere un mRNA?». RNA positivo: è già mRNA, va tradotto subito. RNA negativo: serve una RNA polimerasi RNA-dipendente portata nel virione. Retrovirus: trascrittasi inversa → DNA → integrasi → provirus. Per il ciclo dei fagi: lisi immediata = litico; DNA integrato che si replica con il batterio = lisogenico (profago), che torna litico dopo un danno al DNA (UV). Per ingresso e uscita: solo i virus con envelope possono fondersi con la membrana ed uscire per gemmazione; i virus nudi escono di solito per lisi. Errore tipico: attribuire ai virus ribosomi, metabolismo o sensibilità agli antibiotici.");
T("b1b").sp.push("Come si ragiona negli esercizi: nella colorazione di Gram il risultato dipende dalla parete: viola = Gram-positivo (peptidoglicano spesso, niente membrana esterna), rosa = Gram-negativo (peptidoglicano sottile + membrana esterna con LPS). Per riconoscere il trasferimento genico usa tre domande: serve contatto tra cellule (pilo)? → coniugazione; il DNA nudo nel mezzo basta ed è sensibile alla DNasi? → trasformazione; il DNA viaggia dentro un fago, resiste alla DNasi e passa un filtro che blocca le cellule? → trasduzione (generalizzata se qualsiasi gene, specializzata se solo i geni vicini al sito di integrazione). Ricorda che il trasferimento è orizzontale: avviene anche tra specie diverse e spiega la rapida diffusione delle resistenze.");
T("b1c").sp.push("Come si ragiona negli esercizi: separa sempre due gruppi. Sistema delle endomembrane (involucro nucleare, RE, Golgi, endosomi, lisosomi, vescicole, membrana plasmatica): compartimenti collegati da vescicole o continui tra loro. Organelli di origine endosimbiotica (mitocondri, cloroplasti): doppia membrana, DNA circolare proprio, ribosomi 70S, divisione per scissione, cardiolipina nella membrana interna. Se una domanda chiede una «prova» dell'endosimbiosi, cerca una somiglianza con i batteri; se chiede il percorso di una proteina secreta, segui RE → Golgi → vescicole → membrana. Per le dimensioni usa gli ordini di grandezza: virus decine-centinaia di nm, batteri 1–5 µm, cellule eucariotiche 10–100 µm.");
T("b1d").sp.push("Come si ragiona negli esercizi: per le macromolecole individua monomero, legame e reazione (condensazione per costruire, idrolisi per demolire). Per gli enzimi le domande sono quasi sempre a coppie opposte: chinasi aggiunge fosfato / fosfatasi lo toglie; acetilasi / deacetilasi; ubiquitina ligasi / deubiquitinasi. Per il DNA usa le regole di Chargaff nella doppia elica (A = T, G = C, quindi A + G = 50%) e ricordati che i filamenti sono antiparalleli: una sequenza complementare si scrive invertendo l'ordine se vuoi leggerla 5'→3'. Per la struttura delle proteine: primaria = sequenza (legami peptidici), secondaria = legami idrogeno dello scheletro, terziaria = interazioni tra catene laterali, quaternaria = più subunità.");
T("b2a").sp.push("Come si ragiona negli esercizi: tieni distinti cromosoma (conta i centromeri), cromatidio e molecola di DNA a doppia elica. In una cellula umana: G1 = 46 cromosomi, 46 molecole di DNA; dopo la fase S (G2, profase, metafase) = 46 cromosomi da 2 cromatidi, cioè 92 cromatidi e 92 molecole di DNA; in anafase i cromatidi si separano e diventano 92 cromosomi monocromatidici. Per il tipo di cromosoma guarda la posizione del centromero (metacentrico, submetacentrico, acrocentrico, telocentrico). Per gli elementi minimi chiediti che cosa succede se manca: senza origini non si replica, senza centromero si perde in mitosi, senza telomeri si accorcia e le estremità vengono scambiate per rotture.");
T("b2b").sp.push("Come si ragiona negli esercizi: ordina i livelli di compattamento (doppia elica 2 nm → collana di perle 11 nm → fibra di 30 nm con H1 → anse su un'impalcatura → cromosoma metafasico) e associa a ciascuno chi lo crea (ottamero H2A-H2B-H3-H4, H1, condensine). Per l'epigenetica collega i segni allo stato della cromatina: acetilazione degli istoni = carica positiva neutralizzata, cromatina aperta, trascrizione; deacetilazione e metilazione delle CpG del promotore = cromatina chiusa, silenziamento. Se un esercizio usa un farmaco (inibitore di HDAC o di DNA metiltransferasi), ragiona su quale segno cambia e in quale direzione si sposta l'espressione. Ricorda: l'epigenetica cambia l'espressione, non la sequenza.");
T("b2c").sp.push("Come si ragiona negli esercizi: classifica la sequenza per numero di copie e disposizione. Copia singola (la maggior parte dei geni); famiglie geniche (copie simili nate da duplicazione: globine, rRNA); ripetute in tandem una dietro l'altra (satellite, minisatelliti/VNTR con unità di 10–100 bp, microsatelliti/STR con unità di 1–6 bp); ripetute intersperse sparse nel genoma (LINE autonomi con trascrittasi inversa, SINE come Alu non autonomi, retrovirus endogeni, trasposoni a DNA con trasposasi). Negli esercizi di identificazione (paternità, forense) ricorda che ogni persona ha due alleli per STR, uno dalla madre e uno dal padre: togli dall'individuo l'allele materno, quello che resta deve essere presente nel padre.");
T("b3a").sp.push("Come si ragiona negli esercizi: scrivi sempre le polarità. Il filamento nuovo è complementare e antiparallelo allo stampo e cresce solo 5'→3' (la polimerasi aggiunge al 3'-OH). Davanti alla forcella: elicasi apre, SSB stabilizzano, topoisomerasi toglie le tensioni; poi primasi (primer di RNA) → DNA polimerasi → rimozione del primer e riempimento → ligasi. Il filamento continuo è quello il cui stampo è orientato 3'→5' nella direzione di avanzamento della forcella; l'altro è discontinuo (frammenti di Okazaki). Per Meselson e Stahl conta le molecole: ogni generazione raddoppia il totale, ma le molecole ibride restano sempre 2 per ogni molecola iniziale. Per i telomeri: accorciamento a ogni divisione → senescenza; telomerasi (RNA stampo + trascrittasi inversa) attiva in cellule germinali, staminali e tumorali.");
T("b3b").sp.push("Come si ragiona negli esercizi: per l'operone lac fai sempre la tabella a due ingressi. Lattosio presente → allolattosio stacca il repressore dall'operatore; glucosio assente → cAMP alto, CAP-cAMP aiuta la polimerasi. Trascrizione forte solo con lattosio SÌ e glucosio NO. Nei mutanti chiediti quale pezzo manca: repressore inattivo o operatore che non lo lega → espressione costitutiva; promotore danneggiato → nessuna trascrizione. Per le sequenze: l'mRNA ha la stessa sequenza del filamento codificante (U al posto di T) ed è complementare e antiparallelo allo stampo. Negli eucarioti distingui le tre RNA polimerasi (I rRNA grandi, II mRNA e molti snRNA/miRNA, III tRNA e 5S), i fattori generali sulla TATA box (TFIID, TFIIH che fosforila la CTD) e i fattori specifici che legano enhancer o silencer, anche lontani.");
T("b3c").sp.push("Come si ragiona negli esercizi: ricostruisci l'mRNA maturo in ordine (cappuccio – 5'UTR – AUG … stop – 3'UTR – poli-A) e chiediti che cosa succede se manca un pezzo: senza cappuccio l'mRNA viene degradato e tradotto male, senza coda di poli-A è instabile, con un sito di splicing mutato (GU…AG) l'introne resta o un esone viene saltato. Nei calcoli di lunghezza somma solo gli esoni: gli introni non arrivano mai nel citoplasma. Per lo splicing alternativo conta le combinazioni ammesse dal testo, senza inventarne altre. Per la stabilità ricorda la sequenza tipica della degradazione: deadenilazione → decapping → esonucleasi; miRNA (appaiamento imperfetto, blocco o degradazione) e siRNA (appaiamento perfetto, taglio) agiscono tramite RISC.");
T("b3d").sp.push("Come si ragiona negli esercizi: prima trova il quadro di lettura (il primo AUG dopo la 5'UTR), poi dividi in triplette senza saltare nulla e fermati al primo codone di stop (UAA, UAG, UGA), che non codifica amminoacidi. Numero di amminoacidi = (nucleotidi dall'AUG allo stop compreso ÷ 3) − 1. Codone e anticodone sono complementari e antiparalleli: scrivili uno sopra l'altro con le polarità opposte. Ricorda le proprietà del codice: a triplette, non sovrapposto, degenerato (più codoni per un amminoacido, spesso diversi nella terza base: oscillazione), non ambiguo (un codone = un solo amminoacido), quasi universale. Per i siti del ribosoma: A accoglie l'amminoacil-tRNA, P tiene il peptidil-tRNA, E fa uscire il tRNA scarico.");
T("b4a").sp.push("Come si ragiona negli esercizi: riscrivi la sequenza in triplette prima e dopo la mutazione e confronta codone per codone. Sostituzione: silente (stesso amminoacido, spesso alla terza base), missenso (amminoacido diverso), nonsenso (nuovo codone di stop). Inserzione o delezione: se il numero di basi non è multiplo di 3 il quadro di lettura slitta e tutti i codoni a valle cambiano (frameshift); se è multiplo di 3 si aggiunge o si toglie uno o più amminoacidi e il resto è conservato. Transizione = purina↔purina o pirimidina↔pirimidina; transversione = purina↔pirimidina. Per le espansioni di triplette dividi la lunghezza per 3 e confronta con la soglia. Per la riparazione associa danno e via: base alterata → BER, dimeri di timina/lesioni ingombranti → NER, appaiamenti errati → MMR, rottura a doppio filamento → ricombinazione omologa o NHEJ.");
T("b4b").sp.push("Come si ragiona negli esercizi: scrivi i genotipi dei genitori, separa i geni (se indipendenti) e lavora un gene alla volta con il quadrato di Punnett piccolo (1/4, 1/2, 3/4); poi moltiplica (regola del prodotto, eventi indipendenti) o somma (regola della somma, eventi che si escludono). Quando il testo dice «almeno uno» calcola 1 − P(nessuno); quando dice «esattamente uno su due» ricorda i due ordini possibili. Se il fenotipo è già noto (es. figlio sano), restringi lo spazio: da Aa × Aa un figlio sano è portatore con probabilità 2/3. Rapporti atipici in F2 (9:3:4, 12:3:1, 9:7) indicano epistasi; rapporti lontani dal 1:1:1:1 in un testcross indicano associazione: frequenza dei ricombinanti = distanza in cM. Con penetranza incompleta moltiplica per la penetranza.");
T("b4c").sp.push("Come si ragiona negli esercizi: leggi la formula del cariotipo da sinistra: numero totale di cromosomi, cromosomi sessuali, poi le anomalie (+21, del(5p), t(9;22), rob(14;21)). Per contare: aneuploidia = un cromosoma in più o in meno (2n ± 1), poliploidia = interi corredi (3n = 69, 4n = 92). Per la non disgiunzione disegna la meiosi: in meiosi I tutti i gameti sono anomali (metà con due copie, metà con nessuna); in meiosi II metà sono normali e metà anomali. Una non disgiunzione mitotica dopo la fecondazione dà mosaicismo. Le anomalie strutturali bilanciate (traslocazioni reciproche, robertsoniane, inversioni) di solito non danno malattia nel portatore, ma producono gameti sbilanciati: aborti ricorrenti o figli con trisomie parziali o complete.");
T("b4d").sp.push("Come si ragiona negli esercizi: procedi per esclusione. 1) Il carattere salta generazioni o compare in figli di genitori sani? → recessivo; è in ogni generazione con ogni malato figlio di un malato? → dominante. 2) Maschi e femmine colpiti in ugual misura e trasmissione padre→figlio maschio? → autosomico (esclude X e mitocondri). 3) Quasi solo maschi, trasmesso da madri sane? → X recessivo. Padre malato con tutte le figlie malate e nessun figlio maschio malato? → X dominante. Solo dalla madre a tutti i figli? → mitocondriale. Poi calcola: assegna i genotipi certi, usa 2/3 per un fratello sano di un malato autosomico recessivo, 1/2 per la figlia di una portatrice X, e moltiplica lungo l'albero. Attento a «figlio maschio» (condizionata al sesso, 1/2) e «figlio» di sesso ignoto (1/2 × 1/2 = 1/4 per un maschio malato da madre portatrice).");

/* ---------- Esempi svolti ---------- */
T("b1a").es.push(
{q:"Due virus infettano una cellula animale: il virus A ha un genoma a RNA a singolo filamento positivo, il virus B a RNA a singolo filamento negativo. Quale dei due ha bisogno di portare un enzima già pronto nel virione, e perché?",p:["Cosa cerco: come ciascun virus ottiene un mRNA traducibile dai ribosomi della cellula.","Virus A: l'RNA positivo ha la stessa polarità di un mRNA → i ribosomi lo traducono subito; tra le prime proteine prodotte c'è la sua RNA polimerasi RNA-dipendente.","Virus B: l'RNA negativo è complementare all'mRNA → non può essere tradotto; prima va copiato in RNA positivo.","La cellula non possiede RNA polimerasi che copiano RNA su stampo di RNA → il virus B deve portarla con sé nel virione."],r:"Il virus B (RNA negativo, come l'influenza) porta la propria RNA polimerasi RNA-dipendente; il virus A no, perché il suo genoma è già un mRNA."},
{q:"Una coltura di E. coli infettata da un fago continua a crescere normalmente per molte generazioni. Dopo un'esposizione ai raggi UV la coltura diventa limpida in poche ore. Spiega che cosa è successo.",p:["La crescita normale dopo l'infezione esclude il ciclo litico immediato: il fago si è integrato come profago (ciclo lisogenico).","Il profago viene replicato con il cromosoma batterico a ogni divisione, senza produrre virioni.","Gli UV danneggiano il DNA: la risposta al danno inattiva il repressore del fago.","Il profago si escinde ed entra nel ciclo litico: produce nuovi fagi e lisa le cellule → la coltura si schiarisce."],r:"Fago temperato in lisogenia, indotto al ciclo litico dal danno al DNA da UV."});
T("b1b").es.push(
{q:"Dopo la colorazione di Gram un batterio appare rosa. Che cosa si deduce sulla sua parete e perché la penicillina tende a essere meno efficace che su un Gram-positivo?",p:["Rosa = ha perso il cristalvioletto con l'alcol e ha preso la safranina → Gram-negativo.","Parete Gram-negativa: strato sottile di peptidoglicano + membrana esterna con LPS e porine.","La penicillina blocca la sintesi del peptidoglicano, ma deve prima attraversare la membrana esterna, che fa da barriera.","Controllo: nei Gram-positivi il peptidoglicano spesso è esposto e trattiene il cristalvioletto (viola)."],r:"È un Gram-negativo: poco peptidoglicano e una membrana esterna che ostacola l'ingresso della penicillina."},
{q:"Un ceppo A resistente a un antibiotico e un ceppo B sensibile sono separati da un filtro che lascia passare molecole di DNA e piccoli virus ma non le cellule. Il ceppo B diventa resistente anche se nel mezzo si aggiunge DNasi. Quale meccanismo di trasferimento genico è avvenuto?",p:["Coniugazione: richiede contatto diretto tra cellule tramite pilo → esclusa dal filtro.","Trasformazione: il DNA nudo nel mezzo verrebbe distrutto dalla DNasi → esclusa.","Trasduzione: il DNA batterico viaggia protetto dentro il capside di un fago, che attraversa il filtro e resiste alla DNasi.","Resta quindi solo la trasduzione."],r:"Trasduzione: unico meccanismo compatibile con il filtro (niente contatto) e con la DNasi (DNA protetto nel fago)."});
T("b1c").es.push(
{q:"Un batterio sferico ha raggio 0,5 µm, una cellula eucariotica sferica ha raggio 5 µm. Confronta il rapporto superficie/volume e spiega perché la cellula grande ha bisogno di membrane interne.",p:["Per una sfera S/V = 4πr² / (4/3 πr³) = 3/r.","Batterio: 3 / 0,5 µm = 6 µm⁻¹.","Cellula eucariotica: 3 / 5 µm = 0,6 µm⁻¹, cioè 10 volte meno superficie per unità di volume.","Le endomembrane (RE, Golgi, mitocondri) aumentano la superficie interna dove avvengono reazioni e trasporti, e separano processi incompatibili."],r:"Il rapporto S/V della cellula eucariotica è 10 volte minore: la compartimentazione compensa la superficie mancante."},
{q:"Di queste osservazioni, quali sostengono l'origine endosimbiotica dei mitocondri? (a) DNA circolare proprio; (b) ribosomi 70S sensibili ad alcuni antibiotici antibatterici; (c) la maggior parte delle proteine mitocondriali è codificata nel nucleo; (d) doppia membrana con cardiolipina nella membrana interna; (e) si dividono per scissione.",p:["Cerco somiglianze con un batterio libero.","(a) DNA circolare e (b) ribosomi 70S: tipici dei batteri → sì.","(d) doppia membrana: quella interna deriva dalla membrana del batterio, quella esterna dalla cellula ospite; la cardiolipina è un lipide batterico → sì. (e) scissione binaria → sì.","(c) non è una prova a favore: indica il trasferimento di geni al nucleo avvenuto dopo l'endosimbiosi, che spiega perché il mitocondrio non è più autonomo."],r:"Sostengono l'endosimbiosi a, b, d, e; la c descrive una conseguenza successiva (trasferimento genico al nucleo)."});
T("b1d").es.push(
{q:"Una molecola di DNA a doppia elica contiene il 22% di citosina. Quali sono le percentuali di G, A e T?",p:["Regola di Chargaff nella doppia elica: C = G e A = T.","G = 22%, quindi C + G = 44%.","A + T = 100% − 44% = 56%.","A = T = 56% / 2 = 28%. Controllo: 22 + 22 + 28 + 28 = 100."],r:"G = 22%, A = 28%, T = 28% (vale per la doppia elica, non per un singolo filamento)."});
T("b2a").es.push(
{q:"Una specie ha 2n = 8. Per una cellula somatica indica cromosomi, cromatidi e molecole di DNA a doppia elica in G1, in metafase mitotica e in anafase mitotica.",p:["G1: 8 cromosomi a un solo cromatidio → 8 cromatidi, 8 molecole di DNA.","Fase S: ogni molecola si duplica; i cromosomi restano 8 (stesso numero di centromeri).","Metafase: 8 cromosomi, ciascuno con 2 cromatidi fratelli → 16 cromatidi, 16 molecole di DNA.","Anafase: i cromatidi si separano e ognuno diventa un cromosoma → 16 cromosomi monocromatidici, 16 molecole di DNA."],r:"G1 8/8/8; metafase 8 cromosomi, 16 cromatidi, 16 DNA; anafase 16 cromosomi, 16 DNA. Si contano i centromeri per contare i cromosomi."},
{q:"Si costruisce un cromosoma artificiale di lievito togliendo, a turno, uno degli elementi minimi. Prevedi che cosa succede senza (1) origini, (2) centromero, (3) telomeri.",p:["Senza origini di replicazione il cromosoma non viene duplicato in fase S → si diluisce e si perde con le divisioni.","Senza centromero non si forma il cinetocore → i microtubuli non lo agganciano e in mitosi va a caso in una delle cellule figlie o si perde.","Senza telomeri le estremità si accorciano a ogni replicazione e vengono riconosciute come rotture → degradazione o fusione con altri cromosomi.","Conclusione: servono tutti e tre per un cromosoma lineare stabile."],r:"Ogni elemento ha un compito: replicazione (origini), segregazione (centromero), protezione delle estremità (telomeri)."});
T("b2b").es.push(
{q:"Un genoma diploide di 6 × 10⁹ bp è organizzato in nucleosomi; ogni nucleosoma con il suo DNA linker occupa circa 200 bp. Quanti nucleosomi ci sono circa nel nucleo?",p:["Cosa cerco: numero di unità ripetute nucleosoma + linker.","N = 6 × 10⁹ bp / 200 bp.","200 = 2 × 10², quindi N = (6/2) × 10⁹⁻² = 3 × 10⁷.","Controllo: ogni ottamero lega circa 147 bp, il resto (~50 bp) è linker: l'ordine di grandezza è giusto."],r:"Circa 3 × 10⁷ nucleosomi (30 milioni)."},
{q:"Un gene oncosoppressore è silenziato in un tumore: il suo promotore ha le CpG metilate e gli istoni vicini sono deacetilati. Prevedi l'effetto di un inibitore delle DNA metiltransferasi e di un inibitore delle istone deacetilasi (HDAC).",p:["Il silenziamento è epigenetico: la sequenza del gene è normale.","Inibitore delle DNA metiltransferasi: a ogni replicazione il nuovo filamento non viene metilato → la metilazione si diluisce divisione dopo divisione.","Inibitore delle HDAC: le lisine istoniche restano acetilate → carica positiva neutralizzata, cromatina più aperta.","Entrambi spostano la cromatina verso lo stato di eucromatina → il gene può tornare a essere trascritto."],r:"Entrambi possono riattivare il gene, perché eliminano segni epigenetici di silenziamento senza modificare la sequenza."});
T("b2c").es.push(
{q:"Test di paternità con due microsatelliti (STR). Bambino: locus 1 = 8/12, locus 2 = 15/17. Madre: locus 1 = 8/10, locus 2 = 14/15. Uomo X: 12/13 e 16/17. Uomo Y: 9/12 e 15/16. Chi può essere il padre?",p:["Ogni persona ha due alleli per STR: uno dalla madre, uno dal padre.","Locus 1: la madre ha 8 → l'allele paterno obbligato è 12. X ha 12, Y ha 12: entrambi compatibili.","Locus 2: la madre ha 15 → l'allele paterno obbligato è 17. X ha 17, Y no (15/16).","Y è escluso; X è compatibile su entrambi i loci."],r:"L'uomo X può essere il padre; l'uomo Y è escluso (al locus 2 non ha l'allele 17)."},
{q:"Classifica queste sequenze del genoma umano: (a) (CA)₂₅ in un introne; (b) Alu di circa 300 bp presente in un milione di copie sparse; (c) L1 di 6 kb che codifica una trascrittasi inversa; (d) unità di 171 bp ripetuta migliaia di volte una dietro l'altra al centromero; (e) i geni delle globine β, γ, δ, ε sul cromosoma 11.",p:["Prima domanda: le copie sono una dietro l'altra (tandem) o sparse (intersperse)?","(a) unità di 2 bp in tandem → microsatellite (STR). (d) unità di 171 bp in tandem al centromero → DNA satellite alfa.","(b) breve elemento sparso, non autonomo → SINE. (c) lungo elemento sparso con trascrittasi inversa → LINE (autonomo).","(e) geni simili nati per duplicazione ed espressi in fasi diverse dello sviluppo → famiglia genica."],r:"a microsatellite; b SINE; c LINE; d DNA satellite (tandem); e famiglia genica."});
T("b3a").es.push(
{q:"Un tratto di filamento stampo ha sequenza 3'-TACGGATC-5'. Scrivi il filamento sintetizzato dalla DNA polimerasi indicando le polarità, e indica in che direzione cresce.",p:["Il nuovo filamento è complementare (A–T, G–C) e antiparallelo allo stampo.","Sotto 3'-TACGGATC-5' scrivo base per base: 5'-ATGCCTAG-3'.","La polimerasi aggiunge nucleotidi al 3'-OH → cresce da 5' a 3', cioè leggendo lo stampo da 3' a 5'.","Controllo: nel DNA non c'è U; lette in fila, ogni coppia è A–T o G–C."],r:"5'-ATGCCTAG-3', sintetizzato in direzione 5'→3'."},
{q:"Meselson e Stahl: batteri cresciuti a lungo in ¹⁵N vengono trasferiti in ¹⁴N. Che frazione di DNA ibrido (¹⁵N/¹⁴N) e leggero (¹⁴N/¹⁴N) ci sarà dopo 3 generazioni?",p:["Si parte da 1 molecola pesante (2 filamenti ¹⁵N).","Modello semiconservativo: i 2 filamenti pesanti restano sempre interi, ciascuno in una molecola diversa → sempre 2 molecole ibride.","Dopo 3 generazioni le molecole totali sono 2³ = 8.","Ibride = 2/8 = 1/4; leggere = 6/8 = 3/4; pesanti = 0."],r:"1/4 ibrido e 3/4 leggero: le molecole ibride restano 2 mentre il totale raddoppia a ogni generazione."});
T("b3b").es.push(
{q:"Operone lac di E. coli selvatico: prevedi se i geni lacZYA sono trascritti molto, poco o per niente nelle quattro combinazioni di glucosio e lattosio.",p:["Due interruttori: lattosio (allolattosio stacca il repressore dall'operatore) e glucosio (se assente, cAMP alto → CAP-cAMP attiva).","Glucosio +, lattosio −: repressore legato → trascrizione praticamente assente.","Glucosio +, lattosio +: repressore staccato ma CAP inattivo → trascrizione bassa.","Glucosio −, lattosio −: CAP attivo ma repressore legato → trascrizione assente.","Glucosio −, lattosio +: repressore staccato e CAP-cAMP legato → trascrizione massima."],r:"Trascrizione forte solo senza glucosio e con lattosio; con entrambi è bassa; senza lattosio è spenta."},
{q:"Il filamento codificante di un piccolo gene è 5'-ATGGCTTGA-3'. Scrivi il filamento stampo, l'mRNA e indica quanti amminoacidi codifica.",p:["Il filamento codificante ha la stessa sequenza dell'mRNA, con U al posto di T → mRNA 5'-AUGGCUUGA-3'.","Lo stampo è complementare e antiparallelo al codificante → 3'-TACCGAACT-5' (cioè 5'-TCAAGCCAT-3').","Triplette dell'mRNA: AUG (Met) – GCU (Ala) – UGA (stop).","Lo stop non codifica amminoacidi."],r:"Stampo 3'-TACCGAACT-5'; mRNA 5'-AUGGCUUGA-3'; 2 amminoacidi (Met-Ala)."});
T("b3c").es.push(
{q:"Un gene lungo 10 000 nucleotidi (dal sito di inizio della trascrizione al sito di poliadenilazione) ha 3 esoni di 300, 500 e 400 nucleotidi. Quanto è lungo il pre-mRNA, quanto l'mRNA maturo (senza cappuccio e coda) e quanti nucleotidi di introni vengono rimossi?",p:["Il pre-mRNA è la copia dell'intero tratto trascritto: 10 000 nucleotidi.","L'mRNA maturo contiene solo gli esoni: 300 + 500 + 400 = 1200 nucleotidi.","Gli introni sono la differenza: 10 000 − 1200 = 8800 nucleotidi (due introni, tra esone 1-2 e 2-3).","Controllo: gli esoni comprendono anche le UTR, quindi la parte codificante sarà ancora più corta di 1200."],r:"Pre-mRNA 10 000 nt; mRNA maturo 1200 nt (+ cappuccio e poli-A); introni rimossi 8800 nt (88%)."},
{q:"Nel secondo introne di un gene la sequenza GU all'inizio dell'introne diventa AU. Prevedi le conseguenze sull'mRNA e sulla proteina.",p:["Lo spliceosoma riconosce il sito di splicing al 5' dell'introne grazie al dinucleotide GU (e al sito 3' AG): la mutazione lo distrugge.","Possibilità 1: l'introne 2 non viene rimosso e resta nell'mRNA → codoni in più, spesso uno stop precoce.","Possibilità 2: viene usato il sito 5' dell'introne successivo → l'esone 3 viene saltato.","In entrambi i casi la proteina è alterata o troncata, e l'mRNA con stop precoce può essere degradato."],r:"Splicing anomalo (introne trattenuto o esone saltato): proteina tronca o assente, pur senza cambiare alcun codone."});
T("b3d").es.push(
{q:"Traduci l'mRNA 5'-GCAUGUUUGGCUAGUUUAA-3' usando: AUG = Met, UUU = Phe, GGC = Gly, UAG e UAA = stop.",p:["Cerco il primo AUG: G C | A U G … → inizia dalla terza base.","Divido in triplette da lì: AUG – UUU – GGC – UAG – UUU – AA.","AUG = Met, UUU = Phe, GGC = Gly, UAG = stop: la traduzione si ferma qui.","Quello che segue lo stop (UUU AA) fa parte della 3'UTR e non viene tradotto."],r:"Met-Phe-Gly (3 amminoacidi); lo stop UAG chiude la proteina."},
{q:"Un mRNA maturo è lungo 1500 nucleotidi esclusa la coda di poli-A. La 5'UTR è di 100 nucleotidi e la 3'UTR di 197 nucleotidi. Quanti amminoacidi ha la proteina?",p:["Tratto dall'AUG allo stop compreso = 1500 − 100 − 197 = 1203 nucleotidi.","Codoni = 1203 / 3 = 401.","L'ultimo codone è lo stop, che non codifica amminoacidi: 401 − 1 = 400.","Controllo: 1203 è divisibile per 3, quindi il quadro di lettura è coerente."],r:"400 amminoacidi."});
T("b4a").es.push(
{q:"La sequenza codificante 5'-AUG GCA UUC GGA UAA-3' perde la G del secondo codone (GCA). Scrivi i nuovi codoni e prevedi l'effetto.",p:["Prima: AUG GCA UUC GGA UAA → Met-Ala-Phe-Gly-stop.","Dopo la delezione la sequenza è AUGCAUUCGGAUAA.","Rileggo a triplette dall'AUG: AUG CAU UCG GAU AA… → tutti i codoni dopo il primo sono cambiati e lo stop originale UAA è uscito dal quadro.","Una delezione di 1 base (non multiplo di 3) sposta il quadro di lettura: è un frameshift."],r:"Frameshift: Met-His-Ser-Asp… con sequenza alterata fino al primo stop che capita nel nuovo quadro."},
{q:"Nella corea di Huntington gli alleli normali hanno fino a 26 CAG, quelli patologici 36 o più. In un paziente un allele ha un tratto CAG ininterrotto lungo 135 nucleotidi. È patologico?",p:["Ogni ripetizione è una tripletta di 3 nucleotidi.","Numero di CAG = 135 / 3 = 45.","45 ≥ 36 → allele a penetranza completa.","Le espansioni tendono ad allungarsi nella trasmissione (soprattutto paterna): anticipazione nei figli."],r:"45 ripetizioni CAG: allele patologico."});
T("b4b").es.push(
{q:"Testcross: un individuo AaBb (ricevuto AB da un genitore e ab dall'altro) × aabb dà 420 AB, 380 ab, 110 Ab, 90 aB. I geni sono indipendenti? Se no, a che distanza sono?",p:["Con geni indipendenti ci aspetteremmo circa 1:1:1:1 (250 per classe): non è così → geni associati.","Le classi più numerose (AB, ab) sono le parentali; Ab e aB sono le ricombinanti.","Ricombinanti = 110 + 90 = 200 su 1000 = 20%.","1% di ricombinazione = 1 centiMorgan (cM)."],r:"Geni associati a 20 cM sulla mappa genetica."});
T("b4c").es.push(
{q:"In un ovocita, nella meiosi II, i due cromatidi del cromosoma 21 non si separano. Che tipo di ovocita può risultare e che cariotipo avrà lo zigote con uno spermatozoo normale?",p:["La meiosi I è normale: l'ovocita secondario ha un 21 con due cromatidi.","In meiosi II i cromatidi non si separano: un prodotto riceve due copie del 21, l'altro nessuna (uno dei due finisce nel globulo polare).","Ovocita con due 21 + spermatozoo con un 21 → 47,XX,+21 o 47,XY,+21 (trisomia).","Ovocita senza 21 + spermatozoo normale → 45,XX,−21 o 45,XY,−21 (monosomia, non vitale)."],r:"Trisomia 21 libera (47 cromosomi) o monosomia 21; in meiosi II metà dei prodotti è normale, in meiosi I nessuno."});
T("b4d").es.push(
{q:"Due genitori sani hanno una figlia malata. Quale modalità di trasmissione è più probabile e qual è il rischio per il prossimo figlio?",p:["Genitori sani con figlio malato → il carattere è recessivo.","Se fosse recessivo legato all'X, una figlia malata avrebbe ricevuto l'X mutato dal padre, che sarebbe quindi malato: ma il padre è sano → si esclude l'X recessivo.","Resta autosomico recessivo: entrambi i genitori sono Aa.","Rischio per ogni nuovo figlio: 1/4, indipendente dal sesso e dai figli precedenti."],r:"Autosomica recessiva; rischio 1/4 a ogni gravidanza."});

/* ---------- Domande nuove ---------- */
BIO_QB.push(
/* b1a */
{t:"b1a",k:"m",q:"Perché gli antibiotici non sono efficaci contro le infezioni virali?",o:["perché i virus sono troppo piccoli per assorbirli","perché i virus hanno sempre un involucro impermeabile","perché i virus si moltiplicano solo all'esterno delle cellule","perché i virus non hanno parete, ribosomi propri né metabolismo, cioè i bersagli degli antibiotici","perché i virus degradano gli antibiotici con enzimi propri"],a:3,s:"Gli antibiotici colpiscono strutture batteriche (parete, ribosomi 70S, enzimi metabolici) che i virus non possiedono."},
{t:"b1a",k:"m",q:"Un virus a RNA a singolo filamento di polarità positiva, appena il genoma arriva nel citoplasma:",o:["deve essere prima retrotrascritto in DNA","viene tradotto direttamente dai ribosomi della cellula","deve entrare nel nucleo per essere trascritto dalla RNA polimerasi II","si integra subito nel genoma della cellula","deve essere copiato in RNA negativo prima di qualsiasi traduzione"],a:1,s:"L'RNA positivo ha la stessa polarità di un mRNA: i ribosomi lo traducono subito."},
{t:"b1a",k:"m",q:"Un farmaco antinfluenzale inibisce la neuraminidasi, che taglia l'acido sialico a cui restano attaccati i nuovi virioni. Quale tappa blocca?",o:["l'adsorbimento al recettore","la trascrizione inversa","l'integrazione nel genoma","il rilascio dei virioni dalla superficie della cellula","la sintesi delle proteine del capside"],a:3,s:"Senza neuraminidasi i virioni gemmati restano agganciati alla membrana e non si diffondono."},
{t:"b1a",k:"m",q:"Nel ciclo di HIV, l'integrasi:",o:["copia l'RNA virale in DNA","taglia le poliproteine virali in proteine mature","lega la gp120 al recettore CD4","trascrive il provirus in RNA","inserisce il DNA virale a doppio filamento nel DNA della cellula ospite"],a:4,s:"La trascrittasi inversa fa il DNA, l'integrasi lo inserisce nel cromosoma, la proteasi matura le proteine."},
{t:"b1a",k:"m",q:"Quale enunciato fa parte della teoria cellulare?",o:["tutti gli organismi sono formati da una o più cellule e ogni cellula deriva da una cellula preesistente","le cellule si formano spontaneamente dalla materia organica","i virus sono le cellule più semplici","solo gli animali sono formati da cellule","ogni cellula possiede un nucleo"],a:0,s:"Schleiden, Schwann e Virchow: la cellula è l'unità di base dei viventi e nasce solo da un'altra cellula."},
{t:"b1a",k:"m",q:"Un batteriofago integrato come profago nel cromosoma batterico viene replicato:",o:["solo dopo la lisi della cellula","da una propria DNA polimerasi indipendente dal ciclo cellulare","insieme al cromosoma batterico a ogni divisione della cellula","come RNA nel citoplasma","mai: resta inattivo e si perde alla prima divisione"],a:2,s:"Nel ciclo lisogenico il profago fa parte del cromosoma e passa a tutte le cellule figlie."},
{t:"b1a",k:"c",q:"I virus che infettano i batteri si chiamano ____.",a:["batteriofagi","fagi","batteriofago","fago"],s:"Batteriofagi (o fagi), come T4 e lambda."},
{t:"b1a",k:"c",q:"Nel ciclo ____ il batteriofago si moltiplica subito e distrugge la cellula ospite liberando i nuovi virioni (una parola).",a:["litico"],s:"Ciclo litico: replicazione immediata e lisi; nel lisogenico invece il fago si integra."},
{t:"b1a",k:"c",q:"Il DNA di un retrovirus integrato nel genoma della cellula ospite si chiama ____.",a:["provirus"],s:"Il provirus viene copiato con il genoma della cellula e trascritto dalla RNA polimerasi II."},
/* b1b */
{t:"b1b",k:"m",q:"Un batterio Gram-negativo, rispetto a un Gram-positivo, possiede:",o:["una parete di peptidoglicano più spessa","acidi teicoici abbondanti nella parete","nessuna parete","un nucleo delimitato da membrana","una membrana esterna con LPS e uno strato sottile di peptidoglicano"],a:4,s:"Gram-negativi: peptidoglicano sottile nello spazio periplasmico + membrana esterna con lipopolisaccaride."},
{t:"b1b",k:"m",q:"Nella trasduzione generalizzata il fago:",o:["trasferisce solo il plasmide F","trasferisce per errore un frammento qualsiasi del DNA batterico impacchettato nel capside","trasferisce sempre e solo i geni vicini al proprio sito di integrazione","richiede il contatto diretto tra due batteri","trasferisce DNA nudo liberato nell'ambiente"],a:1,s:"Durante il ciclo litico un capside può contenere per errore DNA batterico qualsiasi e portarlo a un altro batterio."},
{t:"b1b",k:"m",q:"Quale esperimento mostrò per primo la trasformazione batterica?",o:["Meselson e Stahl con gli isotopi dell'azoto","Hershey e Chase con fagi marcati","Griffith con pneumococchi S uccisi e R vivi iniettati nel topo","Watson e Crick con la diffrazione dei raggi X","Mendel con i piselli"],a:2,s:"I batteri R vivi acquisivano dai batteri S uccisi la capacità di formare capsula: un «principio trasformante», poi identificato nel DNA."},
{t:"b1b",k:"m",q:"Un batterio Hfr si differenzia da un F⁺ perché:",o:["è sempre il ricevente nella coniugazione","non possiede pili","ha perso tutti i plasmidi","può solo essere trasformato","ha il fattore F integrato nel cromosoma e può trasferire geni cromosomici"],a:4,s:"Hfr = alta frequenza di ricombinazione: il fattore F integrato trascina con sé parte del cromosoma durante la coniugazione."},
{t:"b1b",k:"m",q:"Perché il trasferimento genico orizzontale è un problema in medicina?",o:["perché diffonde rapidamente geni di resistenza agli antibiotici, anche tra specie diverse","perché trasforma i batteri in cellule eucariotiche","perché fa perdere ai batteri la parete","perché avviene solo nei batteri morti","perché blocca la replicazione dei batteri"],a:0,s:"Plasmidi e fagi possono spostare geni di resistenza tra batteri non imparentati, senza attendere mutazioni."},
{t:"b1b",k:"m",q:"Quali strutture sono presenti in TUTTE le cellule procariotiche?",o:["capsula e flagello","membrana plasmatica, ribosomi 70S e cromosoma nel nucleoide","membrana esterna e LPS","plasmidi di resistenza","pili sessuali e fimbrie"],a:1,s:"Capsula, flagelli, pili, plasmidi e membrana esterna sono presenti solo in alcuni procarioti."},
{t:"b1b",k:"c",q:"Il polimero di zuccheri e brevi peptidi che forma la parete dei batteri si chiama ____.",a:["peptidoglicano","mureina"],s:"Il peptidoglicano (mureina) è il bersaglio di penicilline e lisozima."},
{t:"b1b",k:"c",q:"I batteri capaci di assorbire DNA libero dall'ambiente si dicono ____ (una parola).",a:["competenti"],s:"La competenza è necessaria per la trasformazione."},
{t:"b1b",k:"c",q:"La regione del citoplasma batterico occupata dal cromosoma circolare, senza membrana che la delimiti, si chiama ____.",a:["nucleoide"],s:"Nei procarioti non c'è nucleo: il DNA sta nel nucleoide."},
/* b1c */
{t:"b1c",k:"m",q:"Un ribosoma attaccato alla membrana del reticolo endoplasmatico sta sintetizzando una proteina. Dove andrà più probabilmente questa proteina?",o:["nella matrice mitocondriale","nel citosol","nel nucleo","nel perossisoma","lungo la via secretoria: membrane, lisosomi o esterno della cellula"],a:4,s:"Le proteine sintetizzate sul RE ruvido seguono la via RE → Golgi → destinazione finale nel sistema delle endomembrane o fuori dalla cellula."},
{t:"b1c",k:"m",q:"I mitocondri hanno due membrane. Secondo la teoria endosimbiotica, la membrana interna deriva:",o:["dal reticolo endoplasmatico","dalla membrana plasmatica del batterio inglobato","dalla membrana della cellula ospite","dall'involucro nucleare","dall'apparato di Golgi"],a:1,s:"La membrana interna è quella del batterio (con cardiolipina); l'esterna deriva dalla vescicola di inglobamento della cellula ospite."},
{t:"b1c",k:"m",q:"Quale di questi organismi è un eucariote?",o:["Escherichia coli","un archeo metanogeno","il lievito Saccharomyces cerevisiae","un cianobatterio","Streptococcus pneumoniae"],a:2,s:"Il lievito è un fungo unicellulare con nucleo e organuli; gli altri sono procarioti."},
{t:"b1c",k:"m",q:"L'involucro nucleare:",o:["è una singola membrana impermeabile","è una doppia membrana con pori, la cui membrana esterna è continua con il RE","è presente anche nei batteri","deriva da un batterio endosimbionte","non ha pori e si scambia materiale solo per vescicole"],a:1,s:"Due membrane, pori nucleari, membrana esterna in continuità con il reticolo endoplasmatico ruvido."},
{t:"b1c",k:"m",q:"Ordina dal più piccolo al più grande:",o:["batterio < virus < cellula eucariotica animale","virus < cellula eucariotica animale < batterio","cellula eucariotica animale < batterio < virus","virus < batterio < cellula eucariotica animale","batterio < cellula eucariotica animale < virus"],a:3,s:"Virus decine-centinaia di nm, batteri 1–5 µm, cellule eucariotiche 10–100 µm."},
{t:"b1c",k:"m",q:"Il vantaggio principale della compartimentazione della cellula eucariotica è:",o:["eliminare la necessità di ribosomi","rendere superflua la membrana plasmatica","separare reazioni incompatibili e concentrare enzimi e substrati in spazi dedicati","permettere alla cellula di vivere senza ATP","ridurre le dimensioni della cellula"],a:2,s:"Ad esempio gli enzimi idrolitici restano nei lisosomi acidi senza digerire il citosol."},
{t:"b1c",k:"m",q:"Un paramecio è:",o:["un eucariote unicellulare (protista)","un batterio","un archeo","un virus","un organismo pluricellulare"],a:0,s:"I protisti come parameci e amebe sono eucarioti formati da una sola cellula."},
{t:"b1c",k:"c",q:"La membrana mitocondriale interna contiene la ____, un fosfolipide tipico anche delle membrane batteriche.",a:["cardiolipina"],s:"La cardiolipina è una delle prove dell'origine batterica dei mitocondri."},
{t:"b1c",k:"c",q:"Nei pluricellulari cellule con lo stesso genoma si specializzano esprimendo geni diversi: questo processo si chiama ____ cellulare.",a:["differenziazione","differenziamento"],s:"Il genoma è lo stesso; cambia l'insieme dei geni espressi."},
{t:"b1c",k:"c",q:"Il processo con cui una cellula ingloba un'altra cellula intera, alla base dell'endosimbiosi, si chiama ____.",a:["fagocitosi"],s:"Il batterio inglobato non venne digerito ma divenne un ospite permanente."},
/* b1d */
{t:"b1d",k:"m",q:"Una molecola di DNA a doppia elica contiene il 30% di adenina. Qual è la percentuale di guanina?",o:["30%","40%","20%","70%","10%"],a:2,s:"A = T = 30% → A + T = 60%; G + C = 40% → G = 20%."},
{t:"b1d",k:"m",q:"Quale coppia di enzimi ha attività opposte?",o:["chinasi e ubiquitina ligasi","fosfatasi e deubiquitinasi","acetilasi e chinasi","acetiltransferasi (acetilasi) e deacetilasi","DNA polimerasi e DNA ligasi"],a:3,s:"Una aggiunge il gruppo acetile, l'altra lo rimuove: come chinasi/fosfatasi e ubiquitinasi/deubiquitinasi."},
{t:"b1d",k:"m",q:"Se si separano le quattro catene dell'emoglobina senza rompere legami covalenti, quale livello di struttura si perde?",o:["primaria","secondaria","terziaria","tutti i livelli","quaternaria"],a:4,s:"La struttura quaternaria è l'associazione di più subunità; ciascuna catena conserva la propria sequenza e il proprio ripiegamento."},
{t:"b1d",k:"m",q:"Nel modello di Watson e Crick della doppia elica:",o:["le basi sono all'esterno e lo scheletro zucchero-fosfato all'interno","le basi sono all'interno, appaiate con legami idrogeno, e lo scheletro zucchero-fosfato all'esterno","i due filamenti sono paralleli","le coppie sono A–G e C–T","i filamenti sono uniti da legami covalenti tra le basi"],a:1,s:"Basi idrofobiche impilate all'interno; fosfati carichi verso l'acqua; filamenti antiparalleli; A–T e G–C."},
{t:"b1d",k:"c",q:"La regione dell'enzima in cui si lega il substrato e avviene la catalisi si chiama sito ____.",a:["attivo","catalitico"],s:"Il sito attivo ha una forma e cariche complementari al substrato."},
{t:"b1d",k:"c",q:"La reazione inversa della condensazione, che rompe un legame consumando una molecola d'acqua, si chiama ____.",a:["idrolisi"],s:"Digestione di proteine, polisaccaridi e acidi nucleici avviene per idrolisi."},
/* b2a */
{t:"b2a",k:"m",q:"Una cellula umana in metafase mitotica contiene:",o:["92 cromosomi e 92 cromatidi","46 cromosomi e 92 cromatidi","23 cromosomi e 46 cromatidi","46 cromosomi e 46 cromatidi","23 coppie di cromatidi"],a:1,s:"Dopo la fase S i cromosomi restano 46 ma ognuno ha 2 cromatidi fratelli."},
{t:"b2a",k:"m",q:"Una cellula umana in anafase mitotica, prima della citodieresi, contiene:",o:["46 cromosomi e 92 cromatidi","23 cromosomi","92 cromosomi monocromatidici","46 cromosomi monocromatidici","184 cromatidi"],a:2,s:"In anafase i cromatidi fratelli si separano e ognuno diventa un cromosoma: 92 in tutto, 46 per polo."},
{t:"b2a",k:"m",q:"Quante molecole di DNA a doppia elica ci sono nel nucleo di una cellula umana diploide in G2?",o:["46","23","69","92","184"],a:3,s:"In G2 ogni cromosoma ha due cromatidi, e ogni cromatidio è una molecola di DNA: 46 × 2 = 92."},
{t:"b2a",k:"m",q:"Un cromosoma submetacentrico ha:",o:["il centromero leggermente spostato dal centro, con braccio p più corto del braccio q","il centromero proprio all'estremità","due centromeri","nessun centromero","due bracci di uguale lunghezza"],a:0,s:"Metacentrico: bracci uguali; submetacentrico: p un po' più corto; acrocentrico: p cortissimo."},
{t:"b2a",k:"m",q:"Un cromosoma anomalo con due centromeri (dicentrico), durante l'anafase:",o:["si divide sempre normalmente","viene perso perché acentrico","non si condensa","può essere tirato verso poli opposti e rompersi","si trasforma in un telomero"],a:3,s:"Se i due centromeri si agganciano a poli opposti si forma un ponte anafasico che si spezza."},
{t:"b2a",k:"m",q:"La cromatina attorno ai centromeri è tipicamente:",o:["eucromatina ricca di geni attivi","eterocromatina facoltativa come il corpo di Barr","priva di DNA","DNA mitocondriale","eterocromatina costitutiva ricca di DNA ripetuto"],a:4,s:"La regione pericentromerica è eterocromatina costitutiva: sempre condensata, con DNA satellite."},
{t:"b2a",k:"m",q:"Nei nucleosomi del centromero l'istone H3 è sostituito dalla variante:",o:["CENP-A","H1","ubiquitina","H4","SUMO"],a:0,s:"CENP-A marca epigeneticamente il centromero e guida la formazione del cinetocore."},
{t:"b2a",k:"c",q:"Dopo la fase S ogni cromosoma è formato da due cromatidi ____ uniti al centromero.",a:["fratelli"],s:"I cromatidi fratelli sono copie identiche, tenute insieme dalle coesine."},
{t:"b2a",k:"c",q:"La regione del cromosoma in cui i cromatidi fratelli restano più strettamente uniti e su cui si assembla il cinetocore si chiama ____.",a:["centromero"],s:"Il centromero divide il cromosoma nel braccio p e nel braccio q."},
{t:"b2a",k:"c",q:"Una cellula umana in G2 contiene ____ cromatidi (numero).",a:["92"],s:"46 cromosomi × 2 cromatidi = 92."},
/* b2b */
{t:"b2b",k:"m",q:"Quale istone NON fa parte dell'ottamero centrale del nucleosoma?",o:["H2A","H2B","H3","H4","H1"],a:4,s:"L'ottamero è formato da due copie di H2A, H2B, H3, H4; H1 lega il DNA linker all'esterno."},
{t:"b2b",k:"m",q:"Un farmaco inibisce le DNA metiltransferasi in cellule che si dividono più volte. Che cosa succede?",o:["la sequenza del DNA cambia","perdita progressiva della metilazione e possibile riattivazione di geni silenziati","aumento dell'eterocromatina","blocco immediato della trascrizione di tutti i geni","perdita dei nucleosomi"],a:1,s:"Senza metilazione di mantenimento i nuovi filamenti non vengono metilati: la metilazione si diluisce a ogni replicazione."},
{t:"b2b",k:"m",q:"Le isole CpG non metilate si trovano tipicamente:",o:["solo nei telomeri","nel DNA mitocondriale","nei promotori di molti geni attivi","negli introni dei geni silenti","solo nei centromeri"],a:2,s:"Le isole CpG dei promotori attivi non sono metilate; la loro metilazione silenzia il gene."},
{t:"b2b",k:"m",q:"Quale combinazione è tipica dell'eterocromatina?",o:["DNA non metilato e istoni acetilati","istoni iperacetilati e assenza di nucleosomi","DNA metilato, istoni deacetilati, cromatina compatta","cromatina decondensata e trascrizione intensa","DNA non metilato e fibra di 11 nm"],a:2,s:"Metilazione delle CpG e deacetilazione degli istoni favoriscono la compattazione e il silenziamento."},
{t:"b2b",k:"m",q:"Ordina i livelli di compattamento dal meno al più compatto:",o:["fibra di 30 nm → doppia elica → collana di perle → cromosoma metafasico","doppia elica (2 nm) → collana di perle (11 nm) → fibra di 30 nm → anse → cromosoma metafasico","collana di perle → doppia elica → anse → fibra di 30 nm → cromosoma metafasico","doppia elica → fibra di 30 nm → collana di perle → cromosoma metafasico","cromosoma metafasico → anse → fibra di 30 nm → collana di perle → doppia elica"],a:1,s:"Si parte dal DNA nudo, poi i nucleosomi, la fibra con H1, le anse su un'impalcatura, infine il cromosoma condensato."},
{t:"b2b",k:"c",q:"Attorno a ogni ottamero istonico si avvolgono circa ____ coppie di basi di DNA (numero).",a:["147","146","145","150"],s:"Circa 147 bp fanno quasi due giri attorno all'ottamero."},
{t:"b2b",k:"c",q:"Un'informazione epigenetica si trasmette alle cellule figlie senza cambiare la ____ del DNA (una parola).",a:["sequenza"],s:"Cambiano i segni chimici (metilazione, modifiche istoniche), non le basi."},
/* b2c */
{t:"b2c",k:"m",q:"Un bambino ha per un microsatellite gli alleli 9 e 14; la madre ha 9 e 11. Quale di questi uomini può essere il padre?",o:["11/12","9/11","12/14","10/13","11/13"],a:2,s:"Il 9 viene dalla madre; l'allele paterno obbligato è 14, presente solo nell'uomo 12/14."},
{t:"b2c",k:"m",q:"I geni delle globine α e β si trovano:",o:["in un unico gene con molti esoni","sul cromosoma X","nel DNA mitocondriale","in due gruppi su cromosomi diversi (16 e 11), con geni espressi in fasi diverse dello sviluppo","in tandem con i geni degli rRNA"],a:3,s:"Cluster α sul 16 e β sul 11: geni embrionali, fetali e adulti nati per duplicazione."},
{t:"b2c",k:"m",q:"Un elemento LINE-1 completo codifica:",o:["un capside virale","una DNA polimerasi della cellula","l'RNA ribosomale","un istone","una trascrittasi inversa e un'endonucleasi che gli permettono di copiarsi altrove"],a:4,s:"L1 è autonomo: con le proprie proteine si retrotraspone tramite un intermedio a RNA."},
{t:"b2c",k:"m",q:"L'inserzione di un nuovo elemento Alu dentro un esone può:",o:["interrompere il gene e causare una malattia genetica","aumentare il numero dei cromosomi","causare una trisomia","non avere mai effetti","eliminare il centromero"],a:0,s:"Gli elementi mobili possono causare mutazioni per inserzione: sono descritti casi di emofilia e neurofibromatosi."},
{t:"b2c",k:"m",q:"Le famiglie geniche nascono soprattutto per:",o:["trasferimento orizzontale da batteri","duplicazione di un gene ancestrale seguita da divergenza delle copie","fusione di cromosomi","splicing alternativo","editing dell'RNA"],a:1,s:"Le copie duplicate accumulano mutazioni diverse: alcune acquistano nuove funzioni, altre diventano pseudogeni."},
{t:"b2c",k:"c",q:"Un microsatellite (CA)ₙ con n = 20 ha un tratto ripetuto lungo ____ coppie di basi (numero).",a:["40"],s:"20 ripetizioni × 2 bp = 40 bp."},
{t:"b2c",k:"c",q:"I trasposoni a DNA si spostano con un meccanismo «taglia e incolla» grazie all'enzima ____.",a:["trasposasi"],s:"La trasposasi riconosce le ripetizioni invertite alle estremità del trasposone."},
{t:"b2c",k:"c",q:"Il DNA ____ alfa, con unità di 171 bp ripetute in tandem, forma i centromeri umani (una parola).",a:["satellite"],s:"Il DNA satellite è DNA altamente ripetuto in tandem."},
/* b3a */
{t:"b3a",k:"m",q:"Il filamento stampo ha sequenza 3'-ATGCCA-5'. Il filamento sintetizzato dalla DNA polimerasi è:",o:["5'-ATGCCA-3'","5'-UACGGU-3'","5'-TACGGT-3'","5'-ACCGTA-3'","3'-TACGGT-5'"],a:2,s:"Complementare (A–T, G–C) e antiparallelo: sotto il 3' dello stampo c'è il 5' del nuovo filamento."},
{t:"b3a",k:"m",q:"In quale ordine intervengono gli enzimi per completare un frammento sul filamento ritardato?",o:["ligasi → primasi → DNA polimerasi","DNA polimerasi → primasi → ligasi → nucleasi","topoisomerasi → ligasi → primasi","elicasi → ligasi → primasi → DNA polimerasi","primasi → DNA polimerasi → rimozione del primer e riempimento → ligasi"],a:4,s:"Primer di RNA, allungamento, sostituzione del primer con DNA, saldatura del nick con la ligasi."},
{t:"b3a",k:"m",q:"Le cellule di un tumore si dividono indefinitamente senza accorciare i telomeri. Quale enzima è più probabilmente riattivato?",o:["primasi","telomerasi","DNA ligasi","topoisomerasi II","elicasi"],a:1,s:"La telomerasi riallunga i telomeri ed è attiva in circa l'85-90% dei tumori."},
{t:"b3a",k:"m",q:"Perché la DNA polimerasi non può iniziare da sola un nuovo filamento?",o:["perché può aggiungere nucleotidi solo a un 3'-OH già appaiato allo stampo","perché sintetizza solo in direzione 3'→5'","perché non riconosce la timina","perché non ha attività esonucleasica","perché lavora solo su stampi di RNA"],a:0,s:"Serve un innesco: la primasi sintetizza un breve primer di RNA con un 3'-OH libero."},
{t:"b3a",k:"m",q:"Meselson e Stahl, dopo una sola generazione in ¹⁴N, osservarono un'unica banda di densità intermedia. Quale modello fu escluso?",o:["semiconservativo","conservativo","dispersivo","nessuno","tutti e tre"],a:1,s:"Il modello conservativo avrebbe dato una banda pesante e una leggera; il dispersivo fu escluso dopo, con la seconda generazione."},
{t:"b3a",k:"m",q:"La telomerasi è attiva soprattutto in:",o:["neuroni maturi","globuli rossi","tutte le cellule somatiche differenziate","batteri","cellule germinali, staminali e tumorali"],a:4,s:"Nelle cellule somatiche è quasi assente: i telomeri si accorciano e si arriva alla senescenza."},
{t:"b3a",k:"c",q:"Il cromosoma circolare di E. coli si replica in modo ____ a partire da oriC, con due forcelle che si allontanano (una parola).",a:["bidirezionale"],s:"Le due forcelle si incontrano dalla parte opposta del cerchio, nella regione di terminazione."},
{t:"b3a",k:"c",q:"Nell'esperimento di Meselson e Stahl, dopo una generazione in ¹⁴N il DNA forma una banda di densità ____ (una parola).",a:["intermedia","ibrida"],s:"Ogni molecola ha un filamento vecchio (¹⁵N) e uno nuovo (¹⁴N)."},
/* b3b */
{t:"b3b",k:"m",q:"Un mutante lac ha un repressore che non riesce a legare l'operatore. Senza lattosio e senza glucosio l'operone è:",o:["sempre spento","trascritto lo stesso: espressione costitutiva","trascritto solo in presenza di glucosio","trascritto solo dopo l'aggiunta di lattosio","spento perché manca CAP"],a:1,s:"Senza repressore funzionante l'operatore resta libero: la trascrizione non dipende più dal lattosio."},
{t:"b3b",k:"m",q:"Un mutante lac ha il promotore danneggiato, che l'RNA polimerasi non riconosce. Con lattosio e senza glucosio:",o:["la trascrizione è massima","viene trascritto solo lacZ","viene trascritto solo con glucosio","il repressore si stacca e la trascrizione parte comunque","i geni lacZ, lacY e lacA non vengono trascritti"],a:4,s:"Se la polimerasi non si lega al promotore, staccare il repressore e attivare CAP non serve."},
{t:"b3b",k:"m",q:"Il complesso CAP-cAMP sull'operone lac:",o:["reprime la trascrizione quando c'è lattosio","si forma quando il glucosio è abbondante","aumenta la trascrizione quando il glucosio è scarso","lega l'allolattosio","taglia l'mRNA policistronico"],a:2,s:"Poco glucosio → cAMP alto → CAP-cAMP si lega vicino al promotore e favorisce l'RNA polimerasi."},
{t:"b3b",k:"m",q:"Il filamento stampo di un gene è 3'-TACCGGATT-5'. L'mRNA trascritto è:",o:["5'-ATGGCCTAA-3'","5'-UACCGGAUU-3'","3'-AUGGCCUAA-5'","5'-AUGGCCUAA-3'","5'-AAUCCGGUA-3'"],a:3,s:"Complementare e antiparallelo allo stampo, con U al posto di T: AUG-GCC-UAA (Met-Ala-stop)."},
{t:"b3b",k:"m",q:"La TATA box dei promotori eucariotici si trova di solito:",o:["circa 25-30 bp a monte del sito di inizio della trascrizione","al 3' del gene, dopo il codone di stop","nel primo introne","dentro il codone AUG","migliaia di bp a valle del gene"],a:0,s:"È riconosciuta da TBP (parte di TFIID) e posiziona l'RNA polimerasi II."},
{t:"b3b",k:"m",q:"Il filamento codificante (o senso) di un gene è:",o:["quello letto dall'RNA polimerasi","quello complementare all'mRNA","quello con la stessa sequenza dell'mRNA (con T al posto di U)","il filamento ritardato della replicazione","quello che viene trascritto in tRNA"],a:2,s:"La polimerasi legge lo stampo; l'mRNA risulta uguale al filamento codificante."},
{t:"b3b",k:"m",q:"Un fattore di trascrizione specifico possiede tipicamente:",o:["un'attività di RNA polimerasi","un anticodone","un sito di splicing","un dominio di legame al DNA e un dominio di attivazione (o di repressione)","un dominio chinasico che fosforila le basi del DNA"],a:3,s:"Il dominio di legame riconosce una sequenza (es. un enhancer); l'altro dominio recluta coattivatori o il macchinario generale."},
{t:"b3b",k:"c",q:"Nell'operone lac il gene ____ codifica la β-galattosidasi (sigla).",a:["lacZ","lac Z","Z"],s:"lacZ = β-galattosidasi, lacY = permeasi, lacA = transacetilasi."},
{t:"b3b",k:"c",q:"Le sequenze regolative che agiscono solo sul gene posto sulla stessa molecola di DNA si dicono elementi in ____ (una parola latina).",a:["cis"],s:"Promotori, operatori, enhancer sono elementi in cis; le proteine che li legano agiscono in trans."},
/* b3c */
{t:"b3c",k:"m",q:"Un pre-mRNA ha 5 esoni. Lo splicing alternativo può includerli tutti oppure saltare un solo esone interno (2, 3 o 4). Quante isoforme diverse si possono ottenere?",o:["3","5","2","4","8"],a:3,s:"Una isoforma completa + tre isoforme ciascuna senza un esone interno = 4."},
{t:"b3c",k:"m",q:"Una mutazione cambia il dinucleotide GU all'inizio di un introne in AU. La conseguenza più probabile è:",o:["l'mRNA non riceve il cappuccio","il gene non viene più trascritto","lo splicing è alterato: l'introne può restare nell'mRNA o un esone può essere saltato","la proteina avrà un solo amminoacido diverso","nessuna, perché gli introni non contano"],a:2,s:"GU al 5' e AG al 3' dell'introne sono riconosciuti dallo spliceosoma: se mancano lo splicing va storto."},
{t:"b3c",k:"m",q:"Un mRNA maturo eucariotico contiene, dal 5' al 3':",o:["cappuccio, 5'UTR, codone d'inizio, sequenza codificante, codone di stop, 3'UTR, coda di poli-A","coda di poli-A, 3'UTR, codone d'inizio, sequenza codificante, cappuccio","cappuccio, codone di stop, sequenza codificante, codone d'inizio, poli-A","5'UTR, cappuccio, codone d'inizio, introni, poli-A","cappuccio, introni, esoni, poli-A, 5'UTR"],a:0,s:"Il cappuccio è all'estremità 5', la coda di poli-A al 3'; le UTR fiancheggiano la regione codificante."},
{t:"b3c",k:"m",q:"Quale funzione NON è svolta dal cappuccio al 5' dell'mRNA?",o:["protegge l'mRNA dalle esonucleasi","favorisce l'esportazione dal nucleo","aiuta il ribosoma a riconoscere l'mRNA","favorisce lo splicing del primo introne","codifica la metionina iniziale"],a:4,s:"Il cappuccio è una 7-metilguanosina legata 5'-5': non è un codone e non codifica amminoacidi."},
{t:"b3c",k:"c",q:"Al 3' di ogni tRNA maturo si trova la sequenza ____, a cui si lega l'amminoacido (tre lettere).",a:["CCA"],s:"La sequenza CCA viene aggiunta durante la maturazione; l'amminoacido si attacca all'A terminale."},
{t:"b3c",k:"c",q:"Il tratto di un gene che resta nell'mRNA maturo dopo lo splicing si chiama ____.",a:["esone"],s:"Gli esoni restano, gli introni vengono rimossi."},
{t:"b3c",k:"c",q:"La produzione di più proteine dallo stesso pre-mRNA, combinando gli esoni in modi diversi, si chiama splicing ____.",a:["alternativo"],s:"Grazie allo splicing alternativo circa 20 000 geni producono molte più proteine."},
/* b3d */
{t:"b3d",k:"m",q:"L'mRNA 5'-GCAUGGCUUAAGUGA-3', a partire dal primo AUG, codifica quanti amminoacidi?",o:["1","3","2","4","5"],a:2,s:"Dall'AUG: AUG – GCU – UAA: due amminoacidi (Met, Ala), poi lo stop UAA."},
{t:"b3d",k:"m",q:"Una proteina di 300 amminoacidi è codificata da un tratto di mRNA, dal codone d'inizio allo stop compreso, lungo:",o:["300 nucleotidi","900 nucleotidi","906 nucleotidi","100 nucleotidi","903 nucleotidi"],a:4,s:"300 codoni per gli amminoacidi + 1 codone di stop = 301 codoni × 3 = 903 nucleotidi."},
{t:"b3d",k:"m",q:"Con AUG = Met, UUU = Phe, GGC = Gly, UAG = stop, l'mRNA 5'-AUGUUUGGCUAGUUU-3' dà il peptide:",o:["Met-Phe-Gly-Phe","Met-Phe-Gly","Phe-Gly","Gly-Phe-Met","Met-Phe-Gly-Stop-Phe"],a:1,s:"La traduzione si ferma allo stop UAG: l'ultimo UUU non viene tradotto."},
{t:"b3d",k:"m",q:"L'anticodone 5'-CAU-3' si appaia con il codone:",o:["5'-GUA-3'","5'-CAU-3'","5'-UAC-3'","5'-AUG-3'","5'-GTA-3'"],a:3,s:"Appaiamento antiparallelo: il 5' dell'anticodone (C) si appaia con il 3' del codone (G) → codone 5'-AUG-3'."},
{t:"b3d",k:"m",q:"L'oscillazione (wobble) spiega perché:",o:["un tRNA può riconoscere più codoni che differiscono nella terza base","un codone può codificare più amminoacidi","il ribosoma può leggere l'mRNA in entrambe le direzioni","esistono tre codoni di stop","l'mRNA viene letto a coppie di basi"],a:0,s:"L'appaiamento tra la terza base del codone e la prima dell'anticodone è meno rigido: servono meno di 61 tRNA."},
{t:"b3d",k:"m",q:"Durante l'allungamento, il tRNA che porta la catena polipeptidica in crescita si trova nel sito:",o:["A","E","P","di legame del cappuccio","della subunità minore libera"],a:2,s:"Sito A: arriva l'amminoacil-tRNA; sito P: peptidil-tRNA; sito E: esce il tRNA scarico."},
{t:"b3d",k:"c",q:"Il codice genetico si dice non ____ perché ogni codone specifica un solo amminoacido (una parola).",a:["ambiguo"],s:"Degenerato (più codoni per un amminoacido) ma non ambiguo (un codone, un amminoacido)."},
{t:"b3d",k:"c",q:"Con le 4 basi lette a coppie si otterrebbero solo ____ combinazioni, troppo poche per 20 amminoacidi (numero).",a:["16"],s:"4² = 16 < 20; a triplette 4³ = 64, più che sufficienti."},
{t:"b3d",k:"c",q:"Le proteine che aiutano altre proteine a ripiegarsi correttamente e impediscono l'aggregazione si chiamano ____.",a:["chaperon","chaperone","chaperoni","chaperons"],s:"Ad esempio Hsp70 e le chaperonine Hsp60."},
/* b4a */
{t:"b4a",k:"m",q:"La sequenza codificante 5'-AUG GCA UUC GGA UAA-3' perde la G del secondo codone. Il nuovo secondo codone è:",o:["GCA","AUU","CAU","UUC","CAA"],a:2,s:"AUGGCAUUCGGAUAA senza la G in posizione 4 diventa AUG CAU UCG GAU AA: frameshift."},
{t:"b4a",k:"m",q:"In alcune distrofie (forma di Becker) grandi delezioni nel gene della distrofina eliminano un numero di nucleotidi multiplo di 3 e la malattia è più lieve rispetto alla forma di Duchenne. Perché?",o:["perché la delezione colpisce solo gli introni","perché il quadro di lettura è conservato e si forma una proteina più corta ma in parte funzionante","perché la proteina viene prodotta in quantità doppia","perché il gene viene trascritto da un altro promotore","perché le cellule muscolari riparano la delezione"],a:1,s:"Delezione «in frame»: mancano alcuni amminoacidi, ma il resto della proteina è corretto."},
{t:"b4a",k:"m",q:"Quale mutazione puntiforme ha MENO probabilità di alterare la proteina?",o:["una sostituzione che crea un codone di stop vicino all'inizio","una delezione di una base nel primo esone","una sostituzione nella terza base di un codone","un'inserzione di 2 basi","una sostituzione nel codone AUG d'inizio"],a:2,s:"Per la degenerazione del codice molte sostituzioni alla terza base sono silenti."},
{t:"b4a",k:"m",q:"Un frameshift vicino all'inizio della sequenza codificante è di solito più grave di uno vicino alla fine perché:",o:["cambia il promotore","impedisce la trascrizione","colpisce sempre la metionina","altera tutti i codoni a valle e spesso crea presto un codone di stop","altera il cappuccio dell'mRNA"],a:3,s:"Più a monte avviene lo slittamento, più amminoacidi vengono cambiati o persi."},
{t:"b4a",k:"m",q:"Gli agenti intercalanti (come le acridine) inducono soprattutto:",o:["dimeri di timina","deaminazione della citosina","traslocazioni reciproche","aneuploidie","inserzioni o delezioni di singole basi, cioè frameshift"],a:4,s:"Inserendosi tra le basi distorcono l'elica e fanno «scivolare» la polimerasi."},
{t:"b4a",k:"m",q:"Mutazioni ereditarie nei geni del mismatch repair (es. MLH1, MSH2) predispongono a:",o:["tumori del colon ereditari con instabilità dei microsatelliti","xeroderma pigmentoso","emofilia A","sindrome di Down","fibrosi cistica"],a:0,s:"Sindrome di Lynch: senza MMR gli errori di replicazione si accumulano, soprattutto nelle sequenze ripetute."},
{t:"b4a",k:"c",q:"Una mutazione che sostituisce un amminoacido con un altro si dice ____ (una parola).",a:["missenso","di senso errato"],s:"Missenso: es. Glu → Val nell'anemia falciforme."},
{t:"b4a",k:"c",q:"La sostituzione di una purina con una pirimidina, o viceversa, si chiama ____.",a:["transversione","trasversione"],s:"Transizione: purina↔purina o pirimidina↔pirimidina; transversione: tra le due classi."},
{t:"b4a",k:"c",q:"Una mutazione avvenuta in una cellula del corpo e non nella linea germinale si dice ____ e non si trasmette ai figli (una parola).",a:["somatica"],s:"Le mutazioni somatiche possono causare tumori; solo quelle germinali passano alla progenie."},
/* b4b */
{t:"b4b",k:"m",q:"AaBb × AaBb, geni indipendenti con dominanza completa: probabilità di un figlio con fenotipo dominante per entrambi i caratteri?",o:["3/16","1/16","9/16","3/4","1/4"],a:2,s:"P(A_) = 3/4 e P(B_) = 3/4 → 3/4 × 3/4 = 9/16."},
{t:"b4b",k:"m",q:"Aa × Aa: probabilità che tre figli siano tutti aa?",o:["3/4","1/12","1/16","1/64","27/64"],a:3,s:"Eventi indipendenti: (1/4)³ = 1/64."},
{t:"b4b",k:"m",q:"Aa × Aa, due figli: probabilità che esattamente uno dei due sia aa?",o:["1/4","3/16","1/2","9/16","3/8"],a:4,s:"Due ordini possibili: 2 × (1/4 × 3/4) = 6/16 = 3/8."},
{t:"b4b",k:"m",q:"Nel sistema MN, gli individui MN espongono sui globuli rossi sia l'antigene M sia l'antigene N. È un esempio di:",o:["dominanza incompleta","codominanza","epistasi","pleiotropia","penetranza incompleta"],a:1,s:"Entrambi gli alleli si esprimono pienamente nell'eterozigote: codominanza, come Iᴬ e Iᴮ."},
{t:"b4b",k:"m",q:"I geni A e B distano 20 cM. Un individuo AB/ab (A e B sullo stesso cromosoma) × ab/ab: frequenza dei figli Ab/ab?",o:["10%","20%","40%","5%","25%"],a:0,s:"Ricombinanti totali 20%, divisi in due classi uguali (Ab e aB): 10% ciascuna."},
{t:"b4b",k:"c",q:"Nell'epistasi dominante il rapporto fenotipico tipico in F2 è 12 : 3 : ____ (numero).",a:["1"],s:"Il gene epistatico dominante maschera l'altro in 12/16 dei casi."},
{t:"b4b",k:"c",q:"Da AaBb × AaBb (geni indipendenti) la frazione di figli con genotipo AaBb è ____ (frazione).",a:["1/4","0,25","0.25","4/16"],s:"P(Aa) = 1/2 e P(Bb) = 1/2 → 1/4."},
/* b4c */
{t:"b4c",k:"m",q:"Il cariotipo 47,XX,+21 indica:",o:["un maschio con trisomia 21","una femmina con monosomia 21","una femmina con trisomia 21","una femmina triploide","una femmina portatrice di traslocazione 14;21"],a:2,s:"47 cromosomi, due X (femmina), un 21 in più."},
{t:"b4c",k:"m",q:"In una meiosi i due omologhi del 21 non si separano in meiosi I (seconda divisione normale). Dei quattro prodotti:",o:["tutti sono normali","uno su quattro è anomalo","due sono normali e due hanno due copie del 21","metà ha due copie del 21 e metà nessuna copia","tutti hanno tre copie del 21"],a:3,s:"Entrambi gli omologhi vanno in una cellula: due prodotti disomici e due nullisomici; nessuno normale."},
{t:"b4c",k:"m",q:"Una persona ha alcune cellule 46,XX e altre 47,XX,+21. Più probabilmente si è verificata:",o:["una non disgiunzione mitotica dopo la fecondazione (mosaicismo)","una non disgiunzione nella meiosi paterna","una traslocazione robertsoniana","una triploidia","una delezione del 21"],a:0,s:"Un errore in una divisione dell'embrione crea due linee cellulari diverse: mosaico."},
{t:"b4c",k:"m",q:"Una traslocazione reciproca bilanciata:",o:["comporta sempre la perdita di materiale genetico","riguarda solo cromosomi acrocentrici","scambia segmenti tra due cromosomi non omologhi senza perdita di materiale; il portatore è di solito sano ma può avere gameti sbilanciati","aumenta il numero di cromosomi","è un'aneuploidia"],a:2,s:"Il portatore ha tutto il materiale; i problemi compaiono nella segregazione meiotica."},
{t:"b4c",k:"m",q:"Quanti corpi di Barr si osservano nelle cellule di una persona 47,XXY?",o:["0","2","3","1","dipende dall'età"],a:3,s:"Tutti gli X tranne uno vengono inattivati: 2 X → 1 corpo di Barr."},
{t:"b4c",k:"m",q:"La poliploidia differisce dall'aneuploidia perché:",o:["riguarda solo i cromosomi sessuali","modifica la struttura e non il numero","è sempre compatibile con la vita nell'uomo","varia il numero di interi corredi (3n, 4n) e non di singoli cromosomi","è causata solo da traslocazioni"],a:3,s:"Aneuploidia: 2n ± 1 (es. 47); poliploidia: 3n = 69, 4n = 92."},
{t:"b4c",k:"c",q:"Una cellula con un cromosoma in meno rispetto al corredo diploide (2n − 1) si dice ____.",a:["monosomica","monosomia"],s:"Es. 45,X nella sindrome di Turner."},
{t:"b4c",k:"c",q:"Nel bandeggio G le bande scure sono ricche di coppie ____ e relativamente povere di geni (due lettere).",a:["AT","A-T","A–T"],s:"Le bande chiare sono ricche di GC e di geni."},
/* b4d */
{t:"b4d",k:"m",q:"Due genitori sani hanno avuto un figlio con una malattia autosomica recessiva. Probabilità che i prossimi due figli siano entrambi sani?",o:["3/4","1/16","9/16","1/2","3/16"],a:2,s:"Genitori Aa × Aa: ogni figlio è sano con probabilità 3/4; due figli: 3/4 × 3/4 = 9/16."},
{t:"b4d",k:"m",q:"Un uomo sano, il cui fratello ha la fibrosi cistica (genitori sani), sposa una donna portatrice. Probabilità che il loro primo figlio sia malato?",o:["1/4","1/8","1/3","1/6","1/12"],a:3,s:"Lui è portatore con probabilità 2/3 (è sano); figlio malato: 2/3 × 1/4 = 1/6."},
{t:"b4d",k:"m",q:"In un albero genealogico tutte le figlie di un padre malato sono malate e nessuno dei figli maschi lo è. La modalità più probabile è:",o:["dominante legata all'X","autosomica recessiva","recessiva legata all'X","legata all'Y","mitocondriale"],a:0,s:"Il padre passa il suo X a tutte le figlie e mai ai figli maschi."},
{t:"b4d",k:"m",q:"Una malattia colpisce quasi solo maschi nati da genitori sani e si ritrova anche in uno zio materno. La modalità più probabile è:",o:["autosomica dominante","mitocondriale","legata all'Y","dominante legata all'X","recessiva legata all'X"],a:4,s:"Madri portatrici sane trasmettono l'X mutato ai figli maschi; lo zio materno indica che l'allele viene dalla famiglia della madre."},
{t:"b4d",k:"m",q:"Una madre eterozigote per una malattia autosomica dominante e un padre sano hanno tre figli. Probabilità che almeno uno sia malato?",o:["1/2","7/8","3/8","1/8","3/4"],a:1,s:"P(nessuno malato) = (1/2)³ = 1/8 → P(almeno uno) = 1 − 1/8 = 7/8."},
{t:"b4d",k:"c",q:"Nella trasmissione autosomica dominante, da un genitore malato eterozigote e uno sano, il rischio per ogni figlio è del ____ % (numero).",a:["50"],s:"Il genitore malato trasmette l'allele mutato con probabilità 1/2."},
{t:"b4d",k:"c",q:"Il primo membro della famiglia che porta il medico a studiare l'albero genealogico si chiama ____ (o caso indice).",a:["probando","propositus","proposito"],s:"Il probando si indica con una freccia nell'albero."},
{t:"b4d",k:"c",q:"Un carattere presente in ogni generazione, in cui ogni malato ha almeno un genitore malato, è tipico dell'eredità ____ (dominante o recessiva).",a:["dominante"],s:"I caratteri recessivi invece possono saltare generazioni."}
);
})();
